target.css:
:root {
  --ink: #172535;
  --navy: #203c58;
  --paper: #fffdf7;
  --line: #cbd8df;
  --mist: #edf3f3;
  --teal: #087d78;
  --aqua: #d7f1ed;
  --amber: #b56b16;
  --sand: #fff0cf;
  --red: #cf4d47;
}

* {
  box-sizing: border-box;
}

.tunnel-console {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--navy);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.console-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 12px;
  border-bottom: 1px solid var(--line);
  background: var(--navy);
  color: var(--paper);
}

.title-block .eyebrow,
.specimen-copy .eyebrow {
  margin: 0;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  line-height: 1.2;
}

.title-block h1 {
  margin: 4px 0 0;
  font-size: 21px;
  font-weight: 750;
  letter-spacing: -0.4px;
  line-height: 1;
}

.run-chip {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--red);
  color: var(--paper);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.metrics {
  display: grid;
  grid-template-columns: 1.15fr 1fr 1fr;
  border-bottom: 1px solid var(--line);
  background: var(--mist);
}

.metric {
  display: flex;
  min-height: 82px;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  padding: 10px 13px;
  border-left: 1px solid var(--line);
}

.metric:first-child {
  border-left: 0;
}

.speed-metric {
  background: var(--aqua);
}

.metric-label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
  color: var(--navy);
}

.metric strong {
  font-size: 21px;
  font-weight: 750;
  letter-spacing: -0.5px;
  line-height: 1;
}

.metric small {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0;
}

.trend {
  color: var(--teal);
  font-size: 11px;
  font-weight: 700;
}

.trend.neutral {
  color: var(--navy);
}

.trend.amber {
  color: var(--amber);
}

.specimen {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line);
}

.model-mark {
  display: flex;
  width: 52px;
  height: 52px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 3px;
  margin: 0;
  border: 1px solid var(--teal);
  border-radius: 50%;
  background: var(--aqua);
}

.model-mark span {
  display: block;
  width: 5px;
  border-radius: 5px;
  background: var(--teal);
}

.model-mark span:nth-child(1) {
  height: 14px;
}

.model-mark span:nth-child(2) {
  height: 28px;
}

.model-mark span:nth-child(3) {
  height: 19px;
}

.specimen-copy {
  min-width: 0;
  flex: 1;
}

.specimen-copy .eyebrow {
  color: var(--teal);
}

.specimen-copy h2 {
  margin: 4px 0 2px;
  font-size: 15px;
  font-weight: 750;
  line-height: 1.1;
}

.specimen-copy p:last-child {
  margin: 0;
  color: var(--navy);
  font-size: 12px;
  line-height: 1.25;
}

.status-pill {
  padding: 5px 7px;
  border: 1px solid var(--teal);
  border-radius: 5px;
  color: var(--teal);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.console-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--paper);
}

.console-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--navy);
  font-size: 12px;
  font-weight: 650;
}

.pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--teal);
}

.console-footer nav {
  display: flex;
  gap: 7px;
}

.console-footer button {
  padding: 7px 10px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.outline-button {
  border: 1px solid var(--navy);
  background: var(--paper);
  color: var(--navy);
}

.primary-button {
  border: 1px solid var(--teal);
  background: var(--teal);
  color: var(--paper);
}

